components.style:
.hr-card{position:relative;display:block;overflow:hidden;border-radius:var(--r,16px);text-decoration:none;color:inherit;transition:transform .35s ease,box-shadow .35s ease;isolation:isolate;aspect-ratio:4/5;width:100%;will-change:transform;-webkit-mask-image:-webkit-radial-gradient(white,black)}
.hr-card:hover{transform:none;box-shadow:0 24px 48px -24px rgba(26,23,20,.22)}
.hr-card__media{position:absolute;inset:0;background-size:cover;background-position:center;border-radius:inherit;transition:transform .7s ease;overflow:hidden}
.hr-card__media img{width:100%;height:100%;object-fit:cover;display:block}
.hr-card:hover .hr-card__media{transform:scale(1.05)}
.hr-card__overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(26,23,20,.72) 0%,rgba(26,23,20,.42) 32%,rgba(26,23,20,.12) 58%,rgba(26,23,20,0) 78%);z-index:1}
.hr-card__body{position:absolute;bottom:0;left:0;right:0;padding:22px;z-index:2;color:#fff}
.hr-card__eyebrow{font:600 10px/1 'Inter',sans-serif;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.82);margin:0 0 10px;display:inline-block}
.hr-card__eyebrow--paid{color:#e8c598}
.hr-card__title{font-family:var(--ff-display, 'Gazpacho', Georgia, serif);font-size:clamp(15px,1.25vw,19px);line-height:1.22;letter-spacing:-.005em;margin:0;color:#fff;font-weight:700;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}
.hr-card:not(.hr-card--ed) .hr-card__title{text-shadow:0 1px 6px rgba(0,0,0,.35)}
.hr-card__sub{font:500 12px/1.4 'Inter',sans-serif;color:rgba(255,255,255,.72);margin:6px 0 0}
.hr-card__dek-wrap{display:grid;grid-template-rows:0fr;transition:grid-template-rows .4s cubic-bezier(.4,0,.2,1),margin-top .4s ease;margin-top:0}
.hr-card__dek{font:400 12px/1.55 'Inter',sans-serif;color:rgba(255,255,255,.82);margin:0;overflow:hidden;opacity:0;transition:opacity .3s ease .05s}
.hr-card:hover .hr-card__dek-wrap{grid-template-rows:1fr;margin-top:10px}
.hr-card:hover .hr-card__dek{opacity:1}
.hr-card--lead{aspect-ratio:16/9}
.hr-card--lead .hr-card__title{font-size:clamp(24px,2.6vw,40px);line-height:1.1;letter-spacing:-.01em}
.hr-card--lead .hr-card__body{padding:clamp(24px,3vw,36px)}
.hr-card--lead .hr-card__dek{font:400 14px/1.6 'Inter',sans-serif;color:rgba(255,255,255,.88);max-width:640px;margin:0}
.hr-card--lead:hover .hr-card__dek-wrap{margin-top:14px}
.hr-card__sponsored-strip{position:absolute;top:0;left:0;right:0;z-index:3;padding:18px 24px;display:flex;align-items:center;gap:14px;background:linear-gradient(to bottom,rgba(0,0,0,.55) 0%,rgba(0,0,0,0) 100%);pointer-events:none}
.hr-card__sponsored-label{font:600 10px/1 'Inter',sans-serif;letter-spacing:.16em;text-transform:uppercase;color:#e8c598;flex-shrink:0}
.hr-card__sponsored-by{margin-left:auto;font:500 11px/1 'Inter',sans-serif;color:rgba(255,255,255,.82)}
.hr-card__sponsored-by strong{color:#fff;font-weight:600}
@media(max-width:743.98px){
  .hr-card__sponsored-strip{padding:14px 16px;gap:10px}
  .hr-card__sponsored-label{font-size:9px;letter-spacing:.12em}
  .hr-card__sponsored-by{font-size:10px}
}
.hr-card--ed{aspect-ratio:unset;display:block;background:transparent;border-radius:0;overflow:visible;box-shadow:none !important;-webkit-mask-image:none}
.hr-card--ed:hover{transform:none;box-shadow:none}
.hr-card--ed .hr-card__thumb{display:block;position:relative;aspect-ratio:4/3;border-radius:12px;overflow:hidden;margin-bottom:14px;isolation:isolate}
.hr-card--ed .hr-card__media{position:absolute;inset:0;border-radius:inherit}
.hr-card--ed:hover .hr-card__media{transform:scale(1.04)}
.hr-card--ed .hr-card__overlay{display:none}
.hr-card--ed .hr-card__body{position:static;padding:0;color:var(--ink)}
.hr-card--ed .hr-card__eyebrow{order:-1;color:var(--muted);margin:0 0 10px;font:700 10px/1 'Inter',sans-serif;letter-spacing:.14em;text-transform:uppercase;display:block}
.hr-card--ed .hr-card__eyebrow--paid{color:var(--accent,#ee324b);font-weight:700}
.hr-card--ed .hr-card__title{font-family:'Gazpacho',Georgia,serif;font-weight:700;font-size:19px;line-height:1.22;color:var(--ink);margin:0;letter-spacing:normal;text-shadow:none}
.hr-card--ed .hr-card__sub{color:var(--muted);margin:6px 0 0;font-size:12px;line-height:1.4}
.hr-card--ed .hr-card__dek-wrap{display:block;margin-top:12px}
.hr-card--ed .hr-card__dek{font:400 13px/1.55 'Inter',sans-serif;color:var(--muted);opacity:1;margin:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.hr-card--ed:hover .hr-card__dek-wrap{margin-top:12px}

.ep-brands{display:block}
.ep-brands--ticker{position:relative; overflow-x:clip; overflow-y:visible; margin:48px calc(-1 * var(--pad-h,clamp(24px,4vw,56px))) 0; padding:0; cursor:grab; touch-action:pan-y; -webkit-mask-image:linear-gradient(to right,transparent 0,#000 6%,#000 94%,transparent 100%); mask-image:linear-gradient(to right,transparent 0,#000 6%,#000 94%,transparent 100%)}
.ep-brands--ticker.is-dragging{cursor:grabbing; user-select:none}
.ep-brands--ticker.is-dragging a{pointer-events:none}
.ep-brands--ticker .ep-ticker-track{display:flex; width:max-content; gap:0; align-items:stretch; padding:0 clamp(24px,4vw,56px); will-change:transform}
.ep-brands--ticker .ep-brand{flex:0 0 auto; width:clamp(260px,21vw,340px); padding:32px 36px; text-decoration:none; color:inherit; display:flex; position:relative}
.ep-brands--ticker .ep-brand::before{content:""; position:absolute; left:0; top:50%; transform:translateY(-50%); width:1px; height:64%; background:rgba(17,17,17,.07); pointer-events:none}
.ep-brands--ticker .ep-brand:first-child::before{display:none}
.ep-brands--ticker .ep-brand__card{background:transparent !important; border:0 !important; border-radius:0; box-shadow:none !important; display:flex; flex-direction:column; align-items:center; justify-content:flex-start; gap:14px; width:100%; transition:transform .25s ease}
.ep-brands--ticker .ep-brand:hover .ep-brand__card{transform:translateY(-2px)}
.ep-brands--ticker .ep-brand__logo{height:80px; width:100%; display:flex; align-items:center; justify-content:center}
.ep-brands--ticker .ep-brand__wordmark{font-family:'Gazpacho',Georgia,serif; font-weight:700; font-size:clamp(16px,1.3vw,20px); letter-spacing:.04em; text-align:center; line-height:1.1; text-transform:uppercase; color:var(--ink,#111)}
.ep-brands--ticker .ep-brand__info{text-align:center; width:100%; display:flex; flex-direction:column; align-items:center; gap:4px}
.ep-brands--ticker .ep-brand__name{font:600 11.5px/1.2 'Inter',sans-serif; letter-spacing:.16em; text-transform:uppercase; color:var(--ink,#111); margin:0}
.ep-brands--ticker .ep-brand__desc{font:400 13px/1.5 'Inter',sans-serif; color:var(--muted,#6e655b); margin:8px 0 0; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; max-width:260px; text-align:center}
@media(max-width:599px){
  .ep-brands--ticker .ep-brand{width:clamp(220px,70vw,280px); padding:26px 28px}
  .ep-brands--ticker .ep-brand__logo{height:64px}
}

components.js_snippet:
/* After gsap and /ghar-ticker.js (both defer). */
(function init() {
  if (typeof initTicker !== 'function') { setTimeout(init, 50); return; }
  document.querySelectorAll('.ep-brands--ticker').forEach(function (outer) {
    var track = outer.querySelector('.ep-ticker-track');
    if (!track) return;
    initTicker({ outer: outer, track: track, itemSelector: '.ep-brand' });
  });
})();

/* Touch detection, once, near the top of <body>. initCarousel also checks
   (pointer: coarse); this flag covers the S Pen case. */
(function () {
  var hasTouch = ('ontouchstart' in window) || ((navigator.maxTouchPoints || 0) > 0);
  var isTouch = hasTouch && window.innerWidth < 1024;
  window.__GHAR_IS_TOUCH__ = isTouch;
  if (isTouch) document.documentElement.classList.add('touch-device');
})();

/* After gsap and /ghar-carousel.js have loaded. */
document.querySelectorAll('.dc-section .dc-block:not(.dc-block--projects) .dc-track-outer').forEach(function (outer) {
  initCarousel({
    outer: outer,
    track: outer.querySelector('.dc-track'),
    arrowPrev: outer.querySelector('.dc-arrow--prev'),
    arrowNext: outer.querySelector('.dc-arrow--next'),
    fadeL: outer.querySelector('.dc-fade--l'),
    fadeR: outer.querySelector('.dc-fade--r'),
    snap: 'card',
    widthMode: 'auto',
    cssVarHost: outer.closest('.dc-block'),
    autoplayMs: 4500,
    arrowExcludeSelector: '.dc-arrow'
  });
});

document.addEventListener('DOMContentLoaded', function () {
  var block = document.querySelector('.dc-block--projects');
  var outer = block.querySelector('.rail-outer');
  initCarousel({
    outer: outer,
    track: outer.querySelector('.rail'),
    prevBtn: block.querySelector('.dc-page-btn--prev'),
    nextBtn: block.querySelector('.dc-page-btn--next'),
    snap: 'page',
    widthMode: 'fractional-n',
    cssVarHost: block,
    nVar: '--n',
    centerModeQuery: '(max-width: 899.98px)',
    autoplayMs: 5000
  });
});

/* After gsap and /ghar-carousel.js. The touch-detect IIFE from the chip
   carousel entry must already have run near the top of <body>. */
document.querySelectorAll('.dc-block--projects').forEach(function (block) {
  var outer = block.querySelector('.dc-track-outer');
  initCarousel({
    outer: outer,
    track: outer.querySelector('.dc-track'),
    prevBtn: block.querySelector('.dc-page-btn--prev'),
    nextBtn: block.querySelector('.dc-page-btn--next'),
    snap: 'page',
    widthMode: 'fractional-n',
    cssVarHost: block,
    nVar: '--n',
    centerModeQuery: '(max-width: 899.98px)',
    autoplayMs: 5000
  });
});

/* After gsap and /ghar-carousel.js. One loop wires every strip on the page. */
document.querySelectorAll('.tag-strip-outer').forEach(function (outer) {
  initCarousel({
    outer: outer,
    track: outer.querySelector('.tag-strip'),
    prevBtn: outer.querySelector('.tag-strip-arrow--prev'),
    nextBtn: outer.querySelector('.tag-strip-arrow--next'),
    snap: 'free'
  });
});

var phone = document.getElementById('ownerPhone');

// Set: red border, message shown, aria-invalid="true"
gharFieldError(phone, 'Enter a 10 digit mobile number.');

// Clear: all three reset together
gharFieldError(phone, null);

document.addEventListener('DOMContentLoaded', function () {
  window.Fancybox.bind('[data-fancybox="gallery"]', window.gtFancybox.mergeDefaults({}));
});

var overlay = document.getElementById('exampleOverlay');
var modal = document.getElementById('exampleModal');
var lastTrigger = null;

function openExample(trigger) {
  lastTrigger = trigger || null;
  overlay.classList.add('jm-open');
  modal.classList.add('jm-open');   // main.min.js adds body.jm-scroll-locked + history
}
function closeExample() {
  overlay.classList.remove('jm-open');
  modal.classList.remove('jm-open');
  if (lastTrigger) lastTrigger.focus();  // focus returns to the trigger
}
overlay.addEventListener('click', closeExample);
modal.querySelector('.jm-close').addEventListener('click', closeExample);
document.addEventListener('keydown', function (e) {
  if (e.key === 'Escape' && modal.classList.contains('jm-open')) closeExample();
});

// Open without a trigger, for example after an action completes.
gharShareOpen({ title: 'Page title', label: 'Share this page' });
gharShareClose();

gharToast('Property saved');

gharToast('Could not send the brief', {
  type: 'error',
  body: 'Check your connection and try again.'
});

const dismiss = gharToast('Removed from shortlist', {
  action: { label: 'Undo', onClick: restore }
});

/* syncH(): publish both measured heights (inline on every consumer). */
function syncH(){
  var mh = mainNav.getBoundingClientRect().height;
  document.documentElement.style.setProperty('--mainnav-h', mh + 'px');
  if (subnav){
    var sh = subnav.getBoundingClientRect().height;
    document.documentElement.style.setProperty('--subnav-h', sh + 'px');
  }
}

/* In the page's scroll-collapse handler: hide L1 only through the gate. */
document.body.classList.toggle('mainnav-hidden', shouldCollapse && !!(window.gharCanCollapseNav && window.gharCanCollapseNav()));

var show = window.gharCityMatch(card.getAttribute('data-city'), city);

/* From a non-deferred inline script, wait for the deferred main.min.js */
(function run(){
  if (typeof window.gharCityMatch !== 'function') { setTimeout(run, 50); return; }
  applyFilter();
})();

/* Right before </body>, after <script src="/dist/bpr-reveal.js"></script> */
if (typeof bprReveal === 'function') bprReveal({
  map: [
    [".pp-about",             "js-cascade--rise"],
    [".bpr-intel-grid",       "js-cascade--print"],
    [".pp-contact",           "js-reveal--rise"]
  ]
});

components.style:
/* In the page <style> */
.pswp-link {
  display: block;
  position: relative;
  cursor: zoom-in;
  -webkit-tap-highlight-color: transparent;
}
.pswp-link::after {
  content: '';
  position: absolute;
  top: 12px;
  right: 12px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23111' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M15 3h6v6M14 10l7-7M9 21H3v-6M10 14l-7 7'/></svg>")
    center / 16px no-repeat,
    rgba(255, 255, 255, .92);
  opacity: 0;
  transform: translateY(-3px);
  transition: opacity .2s ease, transform .2s cubic-bezier(.2,.7,.2,1);
  pointer-events: none;
  box-shadow: 0 2px 8px rgba(0, 0, 0, .12);
}
.pswp-link:hover::after,
.pswp-link:focus-visible::after {
  opacity: 1;
  transform: translateY(0);
}
/* Don't double up zoom-in indicator on small carousel cards */
@media (max-width: 600px) {
  .pswp-link::after { display: none; }
}

/* Caption strip at the foot of the open lightbox */
.pswp__caption {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 16px 24px 22px;
  max-width: 720px;
  margin: 0 auto;
  font: 400 13px/1.55 'Inter', sans-serif;
  color: rgba(255, 255, 255, .85);
  text-align: center;
  pointer-events: none;
}
.pswp__caption em { font-style: italic; color: rgba(255, 255, 255, .65); }

@media (max-width: 767px), (max-width: 1024px) and (orientation: portrait) {
  .bpr-hero:not(.bpr-hero--split):not(:has(.bpr-hero__bg)) .bpr-hero__inner { margin-top: 0; padding-top: 32px; }
  .bpr-hero:not(.bpr-hero--split):not(:has(.bpr-hero__bg)) .bpr-hero__logo { margin-top: 0; }
  .bpr-hero__overlay { position: fixed; top: calc(env(safe-area-inset-top, 0px) + 12px); left: 0; right: 0; display: flex; justify-content: space-between; padding: 0 16px; z-index: 46; pointer-events: none; transition: opacity .32s ease; }
  .bpr-hero__overlay > * { pointer-events: auto; }
  .bpr-hero__overlay-btn { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 999px; background: rgba(255,255,255,.5); -webkit-backdrop-filter: blur(22px) saturate(1.8); backdrop-filter: blur(22px) saturate(1.8); border: 1px solid rgba(255,255,255,.22); box-shadow: 0 1px 6px rgba(26,23,20,.12), inset 0 1px 0 rgba(255,255,255,.35); color: var(--ink); text-decoration: none; cursor: pointer; transition: background .18s ease, transform .18s ease; }
  .bpr-hero__overlay-btn:hover { background: rgba(255,255,255,.72); }
  .bpr-hero__overlay-btn:active { transform: scale(.96); }
  .bpr-hero__overlay-btn svg { width: 18px; height: 18px; display: block; }
  body[data-past-image] .bpr-hero__overlay { opacity: 0; pointer-events: none; }
}
@media (min-width: 1025px), (min-width: 768px) and (orientation: landscape) {
  .bpr-hero__overlay { display: none; }
}
.bpr-hero { position: relative; min-height: 100vh; min-height: 100dvh; overflow: hidden; background: #1a1714; color: #fff; display: flex; flex-direction: column; justify-content: flex-end; padding: 0 !important; }
.bpr-hero__bg { position: absolute; inset: 0; overflow: hidden; }
.bpr-hero__bg img { width: 100%; height: 100%; object-fit: cover; transform: scale(1.08); animation: bprKenBurns 22s ease-in-out infinite alternate; }
.bpr-hero__scrim { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.42) 0%, rgba(0,0,0,0) 22%, rgba(0,0,0,0) 45%, rgba(0,0,0,.78) 100%), linear-gradient(90deg, rgba(0,0,0,.34) 0%, rgba(0,0,0,0) 55%); pointer-events: none; }
.bpr-hero__inner { position: relative; z-index: 2; max-width: var(--max-w); width: 100%; margin: 0 auto; padding: clamp(88px, 10vh, 112px) var(--pad-h) clamp(56px, 7vh, 88px); display: flex; flex-direction: column; gap: clamp(16px, 2vw, 24px); }
.bpr-hero__logo { padding: 16px 24px; min-height: 84px; min-width: 84px; max-width: 288px; width: fit-content; align-self: flex-start; border-radius: 18px; background: #fff; border: 1px solid var(--rule); -webkit-backdrop-filter: none; backdrop-filter: none; display: inline-flex; align-items: center; justify-content: center; margin: 0 0 clamp(4px, 1vw, 12px); box-shadow: 0 2px 6px rgba(26,23,20,.08), 0 12px 32px -12px rgba(26,23,20,.2); }
.bpr-hero__logo img { max-height: 56px; max-width: 240px; width: auto; height: auto; object-fit: contain; display: block; }
.bpr-hero__logo__fallback { font-family: 'Gazpacho', Georgia, serif; font-weight: 700; font-size: 22px; color: #fff; line-height: 1; }
.bpr-hero__logo.bpr-hero__logo--dark { background: var(--ink); border-color: var(--ink); -webkit-backdrop-filter: none; backdrop-filter: none; }
.bpr-hero__logo.bpr-hero__logo--brand { background: var(--brand); border-color: var(--brand); -webkit-backdrop-filter: none; backdrop-filter: none; }
.bpr-hero__labels { display: inline-flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.bpr-hero__eyebrow { display: inline-flex; align-items: center; gap: 12px; font: 600 11px/1 'Inter', sans-serif; letter-spacing: .18em; text-transform: uppercase; color: rgba(255,255,255,.82); }
.bpr-hero__name { font-family: 'Gazpacho', Georgia, serif; font-weight: 700; font-size: clamp(40px, 5.6vw, 88px); line-height: 1; letter-spacing: -.022em; color: #fff; margin: 0; max-width: 16ch; text-wrap: balance; }
.bpr-hero__tagline { max-width: 72ch; font: 400 clamp(16px, 1.35vw, 20px)/1.55 'Inter', sans-serif; color: rgba(255,255,255,.86); margin: 0; }
.bpr-hero__metrics { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0; padding: clamp(14px, 1.8vh, 22px) 0; border-top: 1px solid rgba(255,255,255,.16); border-bottom: 1px solid rgba(255,255,255,.16); margin: 8px 0 0; max-width: none; }
.bpr-hero__metric { flex: 1 1 180px; padding: 4px clamp(18px, 2.2vw, 32px); border-left: 1px solid rgba(255,255,255,.16); min-width: 0; }
.bpr-hero__metric:first-child { border-left: 0; padding-left: 0; }
.bpr-hero__metric-num { display: block; font: 700 clamp(22px, 2.4vw, 32px)/1 'Gazpacho', Georgia, serif; letter-spacing: -.02em; color: #fff; margin-bottom: 6px; }
.bpr-hero__metric-label { font: 500 12px/1.35 'Inter', sans-serif; color: rgba(255,255,255,.7); letter-spacing: .04em; }
@media (max-width: 900px) {
  .bpr-hero__metric { flex-basis: calc(50% - 1px); padding: 12px 14px; }
  .bpr-hero__metric:nth-child(odd) { border-left: 0; padding-left: 0; }
}
@media (max-width: 560px) {
  .bpr-hero__metric { flex-basis: 100%; border-left: 0; padding: 10px 0; border-top: 1px solid rgba(255,255,255,.16); }
  .bpr-hero__metric:first-child { border-top: 0; padding-top: 0; }
}
.bpr-hero__metrics + .bpr-hero__meta-row { border-top: 0; padding-top: 0; margin-top: 0; }
.bpr-hero__actions { display: flex; flex-wrap: wrap; gap: 12px; margin: 8px 0 0; }
.bpr-hero__actions .bpr-btn--light { background: #fff; color: var(--ink); border-color: #fff; }
.bpr-hero__actions .bpr-btn--light:hover { background: rgba(255,255,255,.9); gap: 14px; }
.bpr-hero__actions .bpr-btn--ghost { background: rgba(255,255,255,.13); -webkit-backdrop-filter: blur(14px) saturate(140%); backdrop-filter: blur(14px) saturate(140%); color: #fff; border-color: rgba(255,255,255,.22); }
.bpr-hero__actions .bpr-btn--ghost:hover { background: rgba(255,255,255,.24); border-color: rgba(255,255,255,.4); gap: 14px; }
.bpr-hero__meta-row { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px 24px; margin-top: 12px; padding-top: 24px; border-top: 1px solid rgba(255,255,255,.16); }
