(function(){
  var toc = document.getElementById('artToc');
  var list = document.getElementById('artTocList');
  var count = document.getElementById('artTocCount');
  var body = document.querySelector('.art-body');
  if (!toc || !list || !body) return;
  var headings = body.querySelectorAll('h2');
  if (headings.length < 3) { toc.style.display = 'none'; return; }
  var slugify = function(s){
    return s.toLowerCase().replace(/[^\w\s-]/g,'').trim().replace(/\s+/g,'-').slice(0,60);
  };
  var seen = {};
  headings.forEach(function(h){
    var id = h.id || slugify(h.textContent);
    var base = id, i = 1;
    while (seen[id]) { i++; id = base + '-' + i; }
    seen[id] = true;
    h.id = id;
    var li = document.createElement('li');
    var a = document.createElement('a');
    a.href = '#' + id;
    a.textContent = h.textContent;
    li.appendChild(a);
    list.appendChild(li);
  });
  if (count) count.textContent = headings.length;
})();

components.style:
.art-disclosure-wrap{max-width: 820px; margin: clamp(16px, 2vw, 22px) auto 0; padding: 0 clamp(24px, 4vw, 56px);}
.art-disclosure{display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 10px; padding: 12px 0; border-top: 1px solid var(--rule, #e8e8e8); border-bottom: 1px solid var(--rule, #e8e8e8); font: 500 12.5px/1.4 'Inter', sans-serif; color: var(--ink, #111);}
.art-disclosure__mark{display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border-radius: 50%; background: var(--ink, #111); color: #fff; font: 700 11px/1 'Gazpacho', Georgia, serif; flex-shrink: 0;}
.art-disclosure__line{color: var(--ink, #111);}
.art-disclosure__brand{font: 700 13px/1 'Gazpacho', Georgia, serif; letter-spacing: -.005em; color: var(--ink, #111); margin-left: 2px;}
.art-disclosure__divider{width: 1px; height: 12px; background: var(--rule, #d8d8d8);}
.art-disclosure__tag{font: 600 9.5px/1 'Inter', sans-serif; letter-spacing: .14em; text-transform: uppercase; color: var(--muted, #6e655b);}
@media (max-width: 480px){
  .art-disclosure{font-size: 12px; gap: 8px;}
  .art-disclosure__mark{width: 20px; height: 20px; font-size: 10.5px;}
  .art-disclosure__brand{font-size: 12.5px;}
  .art-disclosure__tag{font-size: 9px; letter-spacing: .12em;}
}

.art-stat{margin: 56px 0; text-align: center; padding: 36px 0; border-top: 1px solid var(--rule, #e8e8e8); border-bottom: 1px solid var(--rule, #e8e8e8);}
.art-stat__num{font-family: 'Gazpacho', Georgia, serif; font-weight: 700; font-size: clamp(48px, 7vw, 80px); line-height: 1; color: var(--ink, #111); letter-spacing: -.01em;}
.art-stat__caption{font: 400 14px/1.55 'Inter', sans-serif; color: var(--muted, #6e655b); margin: 14px auto 0; max-width: 38ch;}
@media (max-width: 600px){
  .art-stat{padding: 28px 0; margin: 40px 0;}
  .art-stat__num{font-size: 56px;}
  .art-stat__caption{font-size: 13px;}
}
.art-stat-strip{margin: 48px 0; padding: 28px 0; border-top: 1px solid var(--rule, #e8e8e8); border-bottom: 1px solid var(--rule, #e8e8e8); display: grid; grid-template-columns: repeat(auto-fit, minmax(0, 1fr)); gap: 24px;}
.art-stat-strip__item{min-width: 0; text-align: left; padding: 0 4px; position: relative;}
.art-stat-strip__item + .art-stat-strip__item::before{content: ''; position: absolute; left: -12px; top: 6px; bottom: 6px; width: 1px; background: var(--rule, #e8e8e8);}
.art-stat-strip__num{font-family: 'Gazpacho', Georgia, serif; font-weight: 700; font-size: clamp(28px, 3.4vw, 40px); line-height: 1; color: var(--ink, #111); letter-spacing: -.008em; margin: 0 0 10px;}
.art-stat-strip__label{font: 700 10px/1.3 'Inter', sans-serif; letter-spacing: .14em; text-transform: uppercase; color: var(--muted, #6e655b); margin: 0;}
@media (max-width: 600px){
  .art-stat-strip{grid-template-columns: 1fr; padding: 22px 0; gap: 18px;}
  .art-stat-strip__item{padding-left: 0;}
  .art-stat-strip__item + .art-stat-strip__item::before{left: 0; top: -10px; right: 0; bottom: auto; width: auto; height: 1px;}
  .art-stat-strip__num{font-size: 30px;}
}
.art-table-wrap{margin: 40px 0; overflow-x: auto; -webkit-overflow-scrolling: touch;}
.art-table{width: 100%; min-width: 460px; border-collapse: collapse; font: 400 14px/1.5 'Inter', sans-serif; color: var(--ink, #111);}
.art-table thead th{font: 600 11px/1.2 'Inter', sans-serif; letter-spacing: .12em; text-transform: uppercase; color: var(--muted, #6e655b); text-align: left; padding: 12px 24px 12px 0; border-top: 1px solid var(--ink, #111); border-bottom: 1px solid var(--rule, #e8e8e8); white-space: nowrap;}
.art-table tbody td{padding: 14px 24px 14px 0; border-bottom: 1px solid var(--rule, #e8e8e8); vertical-align: top;}
.art-table tbody tr:last-child td{border-bottom: none;}
.art-table--zebra tbody tr:nth-child(even) td{background: rgba(212, 159, 64, 0.05);}
.art-table--minimal{}
.art-table--minimal thead th{border-top: 1px solid var(--ink, #111); border-bottom: 1px solid var(--rule, #e8e8e8);}
.art-table--minimal tbody td{border-bottom: 1px solid rgba(0, 0, 0, .06);}
.art-table--minimal.art-table--zebra tbody tr:nth-child(even) td{background: transparent;}
.art-table--bordered thead th, .art-table--bordered tbody td{border: 1px solid var(--rule, #e8e8e8); padding: 12px 14px;}
.art-table--bordered thead th{background: #f7f5f0; border-top: 2px solid var(--ink, #111);}
.art-table--bordered tbody tr:last-child td{border-bottom: 1px solid var(--rule, #e8e8e8);}
.art-table--row-header tbody td:first-child{font: 700 11px/1.3 'Inter', sans-serif; letter-spacing: .14em; text-transform: uppercase; color: var(--muted, #6e655b); padding-right: 32px; white-space: nowrap; vertical-align: top;}
.art-table--row-header tbody td{padding: 14px 0;}
.art-table--row-header.art-table--zebra tbody tr:nth-child(even) td{background: transparent;}
@media (max-width: 600px){
  .art-table-wrap{margin-left: calc(-1 * clamp(24px, 4vw, 56px)); margin-right: calc(-1 * clamp(24px, 4vw, 56px)); padding: 0 clamp(24px, 4vw, 56px);}
  .art-table, .art-table thead th{font-size: 13px;}
  .art-table thead th, .art-table tbody td{padding-right: 18px;}
}
@media (max-width: 480px){
  .art-table--cards{display: block; min-width: 0;}
  .art-table--cards thead{display: none;}
  .art-table--cards tbody, .art-table--cards tr, .art-table--cards td{display: block; width: 100%;}
  .art-table--cards tbody tr{margin-bottom: 14px; padding: 14px 16px; border: 1px solid var(--rule, #e8e8e8); border-radius: 8px; background: #fff;}
  .art-table--cards tbody tr:last-child{margin-bottom: 0;}
  .art-table--cards tbody td{padding: 8px 0; border-bottom: 1px solid rgba(0, 0, 0, .05);}
  .art-table--cards tbody td:last-child{border-bottom: none; padding-bottom: 0;}
  .art-table--cards tbody td:first-child{padding-top: 0;}
  .art-table--cards tbody td::before{content: attr(data-th); display: block; font: 700 9.5px/1 'Inter', sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--muted, #6e655b); margin-bottom: 4px;}
  .art-table--cards.art-table--zebra tbody tr:nth-child(even) td{background: transparent;}
}
.art-compare{margin: 40px 0; display: grid; grid-template-columns: 1fr auto 1fr; column-gap: 20px; align-items: stretch;}
.art-compare__col{padding: 24px; background: #fff; border: 1px solid var(--rule, #e8e8e8); border-radius: 10px; display: grid; gap: 10px; align-content: start;}
.art-compare__col--ink{background: var(--ink, #111); border-color: var(--ink, #111);}
.art-compare__col--ink .art-compare__label{color: rgba(255,255,255,.65);}
.art-compare__col--ink .art-compare__title{color: #fff;}
.art-compare__col--ink .art-compare__body{color: rgba(255,255,255,.85);}
.art-compare__label{font: 700 9.5px/1 'Inter', sans-serif; letter-spacing: .2em; text-transform: uppercase; color: var(--muted, #6e655b); margin: 0 0 4px;}
.art-compare .art-compare__title{font: 700 18px/1.25 'Gazpacho', Georgia, serif; color: var(--ink, #111); letter-spacing: -.005em; margin: 0;}
.art-compare__body{font: 400 14px/1.6 'Inter', sans-serif; color: var(--ink2, #374151); margin: 0;}
.art-compare__divider{align-self: center; font: 700 11px/1 'Inter', sans-serif; letter-spacing: .18em; text-transform: uppercase; color: var(--muted, #6e655b); padding: 6px 10px; border: 1px solid var(--rule, #e8e8e8); border-radius: 999px; background: #fff;}
@media (max-width: 600px){
  .art-compare{grid-template-columns: 1fr; row-gap: 14px;}
  .art-compare__divider{justify-self: center;}
}

.art-series-foot{max-width: 820px; margin: 0 auto; padding: 48px clamp(24px, 4vw, 56px) 40px; border-top: 1px solid var(--rule, #e8e8e8);}
.art-series-foot__head{display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 24px;}
.art-series-foot__title{font: 700 11px/1 'Inter', sans-serif; letter-spacing: .18em; text-transform: uppercase; color: var(--ink, #111); display: inline-flex; align-items: center; gap: 10px;}
.art-series-foot__title em{font: 600 13px/1 'Inter', sans-serif; letter-spacing: 0; text-transform: none; color: var(--muted, #6e655b); font-style: normal;}
.art-series-foot__progress{display: flex; align-items: center; gap: 6px;}
.art-series-foot__progress span{width: 22px; height: 4px; border-radius: 2px; background: var(--rule, #e8e8e8);}
.art-series-foot__progress span.is-done{background: var(--ink, #111);}
.art-series-foot__progress span.is-current{background: var(--accent, #ee324b);}
.art-series-foot__nav{display: grid; grid-template-columns: 1fr 1fr; gap: 0;}
.art-series-foot__prev, .art-series-foot__next{display: grid; gap: 8px; padding: 22px 24px; background: #fff; border: 1px solid var(--rule, #e8e8e8); text-decoration: none; color: var(--ink, #111); transition: border-color .18s ease, transform .18s ease;}
.art-series-foot__prev{border-radius: 10px 0 0 10px; border-right: 0;}
.art-series-foot__next{border-radius: 0 10px 10px 0; text-align: right;}
.art-series-foot__prev:hover, .art-series-foot__next:hover{border-color: var(--ink, #111); transform: translateY(-1px);}
.art-series-foot__dir{font: 700 9.5px/1 'Inter', sans-serif; letter-spacing: .18em; text-transform: uppercase; color: var(--muted, #6e655b); display: inline-flex; align-items: center; gap: 6px;}
.art-series-foot__next .art-series-foot__dir{justify-content: flex-end;}
.art-series-foot__dir svg{width: 12px; height: 12px;}
.art-series-foot__story-title{font: 700 17px/1.3 'Gazpacho', Georgia, serif; color: var(--ink, #111); letter-spacing: -.005em;}
.art-series-foot__meta{font: 400 12px/1.4 'Inter', sans-serif; color: var(--muted, #6e655b);}
@media (max-width: 600px){
  .art-series-foot{padding: 36px 0 28px;}
  .art-series-foot__nav{grid-template-columns: 1fr;}
  .art-series-foot__prev, .art-series-foot__next{border-radius: 10px; border: 1px solid var(--rule, #e8e8e8); text-align: left;}
  .art-series-foot__prev{margin-bottom: 12px;}
  .art-series-foot__next .art-series-foot__dir{justify-content: flex-start;}
}
.art-tags-wrap{max-width: 820px; margin: 56px auto 0; padding: 32px 0 0; border-top: 1px solid var(--rule, #e8e8e8);}
.art-tags-wrap__label{font: 600 11px/1 'Inter', sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--muted, #6e655b); margin: 0 0 16px;}
.art-tags{display: flex; flex-wrap: wrap; gap: 8px;}
.art-tag{display: inline-flex; align-items: center; padding: 8px 14px; border-radius: 6px; background: #fff; border: 1px solid var(--rule, #e8e8e8); font: 500 12px/1.2 'Inter', sans-serif; color: var(--ink, #111); text-decoration: none; transition: border-color .2s ease, background .2s ease, color .2s ease;}
.art-tag:hover{border-color: var(--ink, #111); background: var(--ink, #111); color: #fff;}
.art-credits{max-width: 820px; margin: 56px auto 0; padding: 40px 0 64px; border-top: 1px solid var(--rule, #e8e8e8);}
.art-credits__head{font: 600 11px/1 'Inter', sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--ink, #111); margin: 0 0 28px;}
.art-credits__grid{display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 36px;}
@media (max-width: 700px){
  .art-credits__grid{grid-template-columns: 1fr; gap: 24px;}
}
.art-credits__col{display: flex; flex-direction: column;}
.art-credits__label{font: 600 10px/1 'Inter', sans-serif; letter-spacing: .14em; text-transform: uppercase; color: var(--muted, #6e655b); margin-bottom: 14px;}
.art-credits__name{font: 600 14.5px/1.3 'Inter', sans-serif; color: var(--ink, #111); text-decoration: none; margin-bottom: 2px; display: block;}
.art-credits__role{font: 400 12px/1.4 'Inter', sans-serif; color: var(--muted, #6e655b); margin-bottom: 16px;}
.art-credits__role:last-child{margin-bottom: 0;}

.cta{position:relative;overflow:hidden;background:var(--ink);color:#fff;border-radius:calc(var(--r) + 8px); padding:clamp(54px,7vw,88px) clamp(28px,5vw,56px);text-align:center;box-shadow:var(--sh); background-image:radial-gradient(60% 60% at 50% -10%,rgba(237, 164, 28,.16) 0%,transparent 62%),radial-gradient(50% 55% at 88% 112%,rgba(213, 97, 58,.14) 0%,transparent 60%)}
.cta__wm{position:absolute;left:-5%;top:-34%;width:min(42vw,360px);opacity:.06;pointer-events:none}
.cta__wm path{fill:#fff}
.cta__inner{position:relative;z-index:2;max-width:640px;margin:0 auto}
.cta__eyebrow{display:inline-block;font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.55);margin-bottom:18px}
.cta h2{color:#fff;margin:0 auto 18px;max-width:18ch}
.cta p{color:rgba(255,255,255,.74);margin:0 auto 36px;max-width:48ch;font-size:clamp(15px,1.7vw,17.5px);line-height:1.7}
.cta__contact{margin:44px auto 0;padding-top:30px;border-top:1px solid rgba(255,255,255,.13);display:flex;flex-wrap:wrap;justify-content:center;gap:16px 14px}
.cta__chip{display:inline-flex;align-items:center;gap:13px;text-decoration:none;padding:10px 20px 10px 12px;border-radius:999px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.04);transition:border-color .25s,background .25s}
.cta__chip:hover{border-color:rgba(255,255,255,.3);background:rgba(255,255,255,.07)}
.cta__chip-ic{width:38px;height:38px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.16);color:#fff}
.cta__chip-ic svg{width:18px;height:18px}
.cta__chip-tx{text-align:left;line-height:1.25}
.cta__chip-tx .lbl{display:block;font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.5)}
.cta__chip-tx .val{display:block;font-size:15px;font-weight:600;color:#fff}

.market{position:relative;margin-top:clamp(20px,2.4vw,26px);display:grid;grid-template-columns:1fr 1fr;align-items:stretch;background:#fff;border:1px solid var(--rule);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}
.market__stat{background:#fff;padding:clamp(28px,3.4vw,38px);display:flex;flex-direction:column}
.market__cap{font:700 11px/1.3 "Inter",sans-serif;letter-spacing:.13em;text-transform:uppercase;color:var(--indigo);margin:0 0 12px}
.market__num{font-family:"Gazpacho",Georgia,serif;font-weight:700;font-size:clamp(34px,4.6vw,52px);line-height:1;color:var(--ink);margin:0}
.market__num span{color:var(--indigo)}
.market__grow{align-self:flex-start;display:inline-flex;align-items:center;gap:7px;margin-top:16px;font:700 12px/1 "Inter",sans-serif;color:#3a4a80;background:#ebeef3;padding:8px 13px;border-radius:999px}
.market__lbl{font-size:14.5px;line-height:1.65;color:var(--espresso);margin:18px 0 0;max-width:42ch}
.market__lbl b{color:var(--ink);font-weight:600}
.market__src{font-size:11.5px;color:var(--muted);margin:13px 0 0;line-height:1.5}
.market__who{position:relative;overflow:hidden;background:#faf7f2;padding:clamp(28px,3.4vw,38px) clamp(28px,3.4vw,38px) clamp(28px,3.4vw,38px) clamp(58px,5.5vw,74px);display:flex;flex-direction:column;justify-content:center;clip-path:polygon(0 0, 100% 0, 100% 100%, 0 100%, 50px 50%)}
.market__who-bg{position:absolute;right:-12%;top:50%;transform:translateY(-50%);width:min(64%,250px);height:auto;opacity:.13;color:var(--indigo);pointer-events:none;z-index:0}
.market__who-lbl,.market__who .aud-list{position:relative;z-index:1}
.market__who-lbl{font:700 10.5px/1 "Inter",sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--indigo);margin:0 0 20px}
.aud-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:15px}
.aud-list li{display:flex;align-items:center;gap:13px;font-size:14.5px;font-weight:600;color:var(--ink);line-height:1.3}
.aud-ic{flex-shrink:0;width:34px;height:34px;border-radius:10px;background:#fff;border:1px solid var(--rule);box-shadow:var(--sh-sm);display:flex;align-items:center;justify-content:center;color:var(--indigo)}
.aud-ic svg{width:18px;height:18px}
@media(max-width:820px){
  .market__who{clip-path:none;border-top:1px solid var(--rule);padding-left:clamp(28px,3.4vw,38px)}
}

.packs{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:6px;align-items:stretch}
.pack--p1{--c:#9aa890;--cd:#5f6e57;--ctint:#f2f4ef}
.pack--p2{--c:#eda41c;--cd:#a07628;--ctint:#fbf3e3}
.pack--p3{--c:#5f71a9;--cd:#56647e;--ctint:#eef0f4}
.pack{border:1px solid var(--rule);border-radius:var(--r);overflow:hidden;display:flex;flex-direction:column;background:#fff;box-shadow:var(--sh);transition:transform .3s cubic-bezier(.2,.7,.2,1),box-shadow .3s}
.pack:not(.pack--feature):hover{transform:translateY(-4px);box-shadow:0 30px 60px -36px rgba(58,53,48,.4)}
.pack--feature{border:none;box-shadow:0 44px 86px -42px rgba(160,118,40,.6);position:relative;z-index:2}
.pack__top{padding:26px 28px 24px;border-bottom:none;color:#fff;background:var(--c); background-image:radial-gradient(135% 100% at 86% 0%,rgba(255,255,255,.42) 0%,transparent 58%), radial-gradient(90% 90% at 4% 116%,rgba(0,0,0,.10) 0%,transparent 56%)}
.pack__badge{display:inline-block;font-size:10.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--cd);background:#fff;padding:5px 11px;border-radius:999px;margin-bottom:13px;box-shadow:0 1px 2px rgba(0,0,0,.06)}
.pack__name{font-family:"Gazpacho",serif;font-weight:700;font-size:29px;color:#fff;line-height:1.06;margin-bottom:7px}
.pack__line{font-size:13.5px;font-weight:600;color:#fff}
.pack__for{font-size:13px;color:rgba(255,255,255,.9);line-height:1.5;margin-top:12px}
.pack__price{margin-top:18px;padding-top:16px;border-top:1px solid rgba(255,255,255,.3);font-family:"Gazpacho",Georgia,serif;font-weight:700;font-size:30px;line-height:1;color:#fff}
.pack__price i{font-family:"Inter",sans-serif;font-size:13px;font-weight:600;font-style:normal;color:rgba(255,255,255,.82);letter-spacing:.01em}
.pack__body{padding:22px 28px 28px;flex:1;display:flex;flex-direction:column}
.pack__body ul{list-style:none;margin:0;padding:0;flex:1}
.pack__body li{position:relative;padding:10px 0 10px 28px;font-size:14.5px;color:var(--espresso);line-height:1.45;border-bottom:1px solid #f0eadf}
.pack__body li:last-child{border-bottom:none}
.pack__body li::before{content:"";position:absolute;left:3px;top:14px;width:12px;height:7px;border-left:2px solid var(--cd);border-bottom:2px solid var(--cd);transform:rotate(-45deg)}
.pack__body li.pack__inherit{padding:0 0 12px;margin-bottom:6px;font-size:13px;font-weight:600;color:var(--muted); text-transform:uppercase;letter-spacing:.04em;border-bottom:1px solid var(--rule)}
.pack__body li.pack__inherit::before{display:none}
.pack__body li.pack__inherit b{color:var(--cd);font-weight:700}
.pack__cta{margin-top:22px;display:flex;align-items:center;justify-content:center;gap:9px;width:100%; padding:14px 20px;border-radius:999px;font:600 15px/1 "Inter",sans-serif;text-decoration:none; border:1.5px solid var(--cd);color:var(--cd);background:#fff; transition:transform .25s cubic-bezier(.2,.7,.2,1),background .25s,color .25s,border-color .25s}
.pack__cta svg{width:15px;height:15px;transition:transform .25s}
.pack__cta:hover{background:var(--cd);color:#fff;transform:translateY(-2px)}
.pack__cta:hover svg{transform:translateX(3px)}
.pack--feature .pack__cta{background:var(--ink);border-color:var(--ink);color:#fff}
.pack--feature .pack__cta:hover{background:#000;border-color:#000}
.packs__note{margin-top:30px;text-align:center;font-size:15px;color:var(--espresso)}
.packs__note b{color:var(--ink)}
@media(max-width:920px){
  .packs{grid-template-columns:1fr;gap:18px;max-width:480px;margin-left:auto;margin-right:auto}
  .pack--feature{transform:none;order:-1}
  .pack:not(.pack--feature):hover{transform:none}
}
@media(max-width:820px){
  .pack--feature{transform:none}
}
@media print{
  .pack,.why__card,.chan,.arcstep{page-break-inside:avoid}
  .pack--feature{transform:none}
}

:root{
  --bg:#ffffff; --warm:#faf7f2; --panel:#f6f1e9; --ink:#1a1714; --espresso:#3a2f27; --muted:#736b62; --rule:#e7e0d4;
  --turmeric:#eda41c; --terracotta:#d5613a; --terracotta-dk:#a85f43; --sand:#e0c199; --sage:#9aa890; --indigo:#7f8ca6;
  --red:#ee324b;
  --r:20px; --rs:13px; --wrap:1140px;
  --pv:clamp(64px,9vw,128px); --ph:clamp(22px,5vw,76px);
  --sh-sm:0 2px 4px rgba(58,53,48,.04);
  --sh:0 30px 60px -44px rgba(58,53,48,.5), 0 4px 12px -8px rgba(58,53,48,.12);
}
*{box-sizing:border-box}
body{margin:0;padding:0;background:var(--bg);color:var(--espresso); font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif; font-size:15px;line-height:1.62;-webkit-font-smoothing:antialiased;}
.disp{font-family:"Gazpacho",Georgia,serif;font-weight:700;letter-spacing:normal}
.band{padding:var(--pv) var(--ph);background:var(--bg);position:relative}
.band--warm{background:var(--warm)}
.wrap{max-width:var(--wrap);margin:0 auto;position:relative;z-index:1}
.eyebrow{display:flex;align-items:center;gap:13px;font-size:12px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);margin:0 0 22px}
.eyebrow .n{font-family:"Gazpacho",serif;font-weight:700;font-size:15px;letter-spacing:0;color:var(--acc,var(--terracotta))}
.eyebrow .n::after{content:"";display:inline-block;width:24px;height:1.5px;background:var(--rule);margin:0 0 4px 11px;vertical-align:middle}
h2{font-family:"Gazpacho",Georgia,serif;font-weight:700;letter-spacing:normal; font-size:clamp(30px,4.6vw,52px);line-height:1.06;color:var(--ink);margin:0 0 20px;max-width:18ch}
.lead{font-size:clamp(16px,1.75vw,20px);line-height:1.6;color:var(--espresso);max-width:60ch;margin:0}
.lead b{color:var(--ink)}
.sub{font-size:clamp(15px,1.6vw,18px);color:var(--muted);max-width:62ch;margin:0 0 40px;line-height:1.62}
strong{color:var(--ink);font-weight:600}
.q-shape{display:inline-block;width:1.22em;height:1.22em;vertical-align:baseline;position:relative;top:.22em;margin:0 .05em;line-height:0}
.q-shape svg{width:100%;height:100%;display:block}
.btn{display:inline-flex;align-items:center;gap:10px;background:var(--red);color:#fff;font-weight:600;font-size:16px;padding:17px 38px;border-radius:999px;text-decoration:none;box-shadow:0 14px 30px -16px rgba(238,50,75,.55);transition:transform .25s cubic-bezier(.2,.7,.2,1),box-shadow .25s}
.btn svg{width:17px;height:17px}
.btn:hover{transform:translateY(-2px);box-shadow:0 20px 38px -16px rgba(238,50,75,.7)}
.btn-ghost{display:inline-flex;align-items:center;gap:9px;background:#fff;color:var(--ink);font-weight:600;font-size:15.5px;padding:16px 30px;border-radius:999px;border:1px solid var(--rule);text-decoration:none;box-shadow:0 14px 30px -14px rgba(26,23,20,.28);transition:background .25s,transform .25s,box-shadow .25s,border-color .25s}
.btn-ghost:hover{transform:translateY(-2px);box-shadow:0 20px 40px -15px rgba(26,23,20,.34)}
.btn-ghost svg{width:16px;height:16px}
@media print{
  .band--warm,.smap,.cta,.pack--feature .pack__top,.why__ic,.market__who,.chan,.arcstep,.pack,.stat,.aud-ic,.cta__chip-ic,.cta__chip,.howstep .n{-webkit-print-color-adjust:exact;print-color-adjust:exact}
  h2{page-break-after:avoid}
}

.hero{padding-top:clamp(40px,6vw,64px);overflow:hidden}
.hero__wm{position:absolute;right:-3%;bottom:-22%;width:min(54vw,540px);opacity:.06;pointer-events:none;z-index:0}
.hero__wm path{fill:var(--terracotta)}
.hero__top{display:flex;align-items:flex-end;gap:16px;margin-bottom:clamp(48px,9vw,104px)}
.hero__top svg{height:30px;width:auto}
.hero__top svg path{fill:var(--red)}
.hero__tag{font-size:12px;font-weight:600;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);padding-left:16px;border-left:1px solid var(--rule)}
.hero h1{font-family:"Gazpacho",Georgia,serif;font-weight:700;letter-spacing:normal; font-size:clamp(38px,6.7vw,82px);line-height:0;color:var(--ink);margin:0 0 30px; display:flex;flex-direction:column;align-items:flex-start}
.hero h1 .t-line{display:block;white-space:nowrap;margin-top:-0.1em}
.hero__lede{font-size:clamp(17px,2.05vw,23px);line-height:1.5;color:var(--espresso);max-width:52ch;margin:0}
.hero__lede b{color:var(--ink);font-weight:600}
.hero__for{margin-top:clamp(40px,6vw,64px);padding-top:24px;border-top:1px solid var(--rule);display:flex;flex-wrap:wrap;gap:8px 9px;align-items:center}
.hero__for-lbl{font-size:11.5px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-right:6px}
.hero__chip{font-size:12.5px;font-weight:600;color:var(--espresso);background:#fff;border:1px solid var(--rule);border-radius:999px;padding:8px 14px;line-height:1;box-shadow:var(--sh-sm)}
.hero__cta{display:flex;flex-wrap:wrap;gap:13px;margin-top:clamp(30px,4vw,40px)}
.hero__cta .btn svg,.hero__cta .btn-ghost svg{width:20px;height:20px}

.alc{margin-top:46px;border-top:1px solid var(--rule);padding-top:40px}
.alc__lbl{font:700 10.5px/1 "Inter",sans-serif;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin:0 0 10px}
.alc__t{font-family:"Gazpacho",serif;font-weight:700;font-size:clamp(20px,2.4vw,26px);color:var(--ink);line-height:1.14;margin:0 0 8px}
.alc__sub{font-size:14.5px;color:var(--muted);line-height:1.6;margin:0 0 30px;max-width:66ch}
.svc{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;margin-top:14px}
.svc__col{display:flex;flex-direction:column}
.svc__grp{margin-top:36px}
.svc__col .svc__grp:first-child{margin-top:4px}
.svc__grp-hd{display:flex;align-items:center;gap:10px;padding-bottom:13px;margin-bottom:4px;border-bottom:1.5px solid var(--rule)}
.svc__grp-dot{width:10px;height:10px;border-radius:50%;background:var(--c,var(--terracotta));flex-shrink:0}
.svc__grp-name{font:700 12.5px/1 "Inter",sans-serif;letter-spacing:.13em;text-transform:uppercase;color:var(--cd,var(--ink))}
.svc__row{padding:11px 0;border-bottom:1px solid #f1ebe0}
.svc__grp .svc__row:last-child{border-bottom:none}
.svc__row-l{display:flex;flex-wrap:wrap;align-items:baseline;column-gap:9px;row-gap:1px}
.svc__row-l b{font-size:14.5px;font-weight:600;color:var(--ink)}
.svc__row-l span{font-size:13px;color:var(--muted);line-height:1.45}
.alc__note{margin-top:34px;font-size:14.5px;color:var(--espresso);text-align:center}
.alc__note b{color:var(--ink)}
.alc__cta{margin-top:22px;text-align:center}
@media(max-width:760px){
  .svc{grid-template-columns:1fr;gap:0}
  .svc__col + .svc__col .svc__grp:first-child{border-top:1px solid var(--rule)}
}

.smap{overflow:hidden;background:#17130f; background-image:radial-gradient(46% 42% at 14% 16%,rgba(237, 164, 28,.16) 0%,transparent 60%),radial-gradient(46% 46% at 86% 22%,rgba(243,126,134,.12) 0%,transparent 60%),radial-gradient(50% 50% at 70% 96%,rgba(127,140,166,.16) 0%,transparent 62%)}
.smap::before{content:"";position:absolute;inset:0;z-index:0;background:repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 1px,transparent 1px 14px);pointer-events:none}
.smap .wrap{position:relative;z-index:1}
.smap__wm{position:absolute;left:-5%;bottom:-30%;width:min(46vw,440px);opacity:.08;pointer-events:none;z-index:0}
.smap__wm path{fill:#fff}
.smap .eyebrow{color:rgba(255,255,255,.8)}
.smap .eyebrow .n{color:#fff}
.smap .eyebrow .n::after{background:rgba(255,255,255,.4)}
.smap h2{color:#fff}
.smap__lead{font-size:clamp(16px,1.75vw,20px);line-height:1.6;color:rgba(255,255,255,.9);max-width:62ch;margin:0}
.smap__lead b{color:#fff}
.smap__grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px;margin-top:clamp(38px,4.5vw,52px)}
.pillar{display:flex;flex-direction:column}
.pillar__hd{display:flex;align-items:center;gap:10px;margin-bottom:16px;padding-bottom:15px;border-bottom:1px solid rgba(255,255,255,.16)}
.pillar__dot{width:11px;height:11px;border-radius:3px;background:var(--c);flex-shrink:0;box-shadow:0 0 16px -2px var(--c)}
.pillar__name{font:700 11.5px/1.25 "Inter",sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#fff}
.chan{position:relative;overflow:hidden;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:16px 17px;margin-bottom:12px;transition:transform .28s cubic-bezier(.2,.7,.2,1),border-color .28s,background .28s}
.chan:last-child{margin-bottom:0}
.chan:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--c) 45%,transparent);background:rgba(255,255,255,.07)}
.chan__t{display:flex;align-items:center;gap:11px;font-family:"Gazpacho",serif;font-weight:700;font-size:15.5px;color:#fff;margin:0 0 8px;line-height:1.1}
.chan__ic{flex-shrink:0;width:32px;height:32px;border-radius:9px;background:color-mix(in srgb,var(--c) 16%,transparent);border:1px solid color-mix(in srgb,var(--c) 38%,transparent);color:var(--c);display:flex;align-items:center;justify-content:center}
.chan__ic svg{width:16px;height:16px}
.chan__d{font-size:12.5px;color:rgba(255,255,255,.72);line-height:1.5;margin:0}
.smap__wrap{margin-top:20px;border-top:1px solid rgba(255,255,255,.14);padding-top:24px}
.smap__wrap-lbl{font:700 11px/1 "Inter",sans-serif;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.6);margin:0 0 16px;text-align:center}
.smap__wrap-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.smap__note{margin-top:clamp(28px,3.4vw,40px);text-align:center;font-size:14.5px;color:rgba(255,255,255,.78)}
.smap__note b{color:#fff}
@media(max-width:1080px){
  .smap__grid{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media(max-width:640px){
  .smap__grid{grid-template-columns:1fr}
}

.why__head{max-width:74ch}
.why__cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:clamp(34px,4vw,46px)}
.why__card{background:#fff;border:1px solid var(--rule);border-radius:var(--r);padding:30px 28px;box-shadow:var(--sh)}
.why__ic{width:52px;height:52px;border-radius:14px;background:var(--terracotta);color:#fff;display:flex;align-items:center;justify-content:center;margin-bottom:20px;box-shadow:0 14px 26px -14px rgba(58,53,48,.55)}
.why__cards .why__card:nth-child(2) .why__ic{background:var(--turmeric)}
.why__cards .why__card:nth-child(3) .why__ic{background:var(--sage)}
.why__ic svg{width:26px;height:26px}
.why__t{font-family:"Gazpacho",serif;font-weight:700;font-size:18px;color:var(--ink);margin:0 0 9px;line-height:1.16}
.why__d{font-size:14px;color:var(--muted);line-height:1.6;margin:0}
@media(max-width:820px){
  .why__cards,.market,.packs,.arc,.em__pts{grid-template-columns:1fr}
}

.cmp{background:var(--navy-2)}
.cmp-wrap{overflow-x:auto;margin-top:30px;border:1px solid rgba(255,255,255,.06)}
.cmp-t{width:100%;min-width:720px;border-collapse:collapse}
.cmp-t th{padding:16px 14px;text-align:center;font-family:var(--ff-d);font-size:14px;font-weight:600;border-bottom:2px solid rgba(255,255,255,.08);color:var(--mute)}
.cmp-t th.ft{color:#fff;background:rgba(238,50,75,.08)}
.cmp-t td{padding:12px 14px;text-align:center;font-size:13px;border-bottom:1px solid rgba(255,255,255,.04);color:rgba(255,255,255,.72)}
.cmp-t td:first-child{text-align:left;font-weight:500;color:#fff;padding-left:20px}
.cmp-t td.ft{background:rgba(238,50,75,.04)}
.chk{color:var(--green);font-size:14px}
.x{color:rgba(255,255,255,.2);font-size:14px}

.faq{background:var(--navy-2)}
.faq-list{margin-top:32px;max-width:820px}
.faq-i{border-bottom:1px solid rgba(255,255,255,.07)}
.faq-q{width:100%;text-align:left;background:none;border:none;padding:18px 0;display:flex;justify-content:space-between;align-items:center;font-family:var(--ff-d);font-size:16px;font-weight:600;color:#fff;gap:20px;transition:color .2s}
.faq-q:hover{color:var(--red)}
.faq-ic{width:24px;height:24px;flex-shrink:0;border:1px solid rgba(255,255,255,.15);display:grid;place-items:center;font-size:15px;color:var(--mute);transition:all .3s}
.faq-i.open .faq-ic{background:var(--red);border-color:var(--red);color:#fff;transform:rotate(45deg)}
.faq-a{max-height:0;overflow:hidden;transition:max-height .4s ease}
.faq-i.open .faq-a{max-height:360px}
.faq-a-in{padding:0 0 22px;font-size:14px;line-height:1.75;color:rgba(255,255,255,.65)}

components.js_snippet:
document.querySelectorAll('.faq-q').forEach(b=>{
    b.addEventListener('click',()=>{
      const item=b.parentElement;
      const open=item.classList.contains('open');
      document.querySelectorAll('.faq-i').forEach(i=>i.classList.remove('open'));
      if(!open)item.classList.add('open');
    });
  });

components.style:
.ts{background:var(--navy)}
.ts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:36px}
.ts-c{background:var(--navy-2);padding:30px 26px;border-top:3px solid rgba(238,50,75,.3)}
.ts-q{font-family:var(--ff-d);font-size:60px;line-height:.7;color:rgba(238,50,75,.18);margin-bottom:8px}
.ts-t{font-size:14px;line-height:1.7;color:rgba(255,255,255,.82);font-style:italic;margin-bottom:20px}
.ts-n{font-family:var(--ff-d);font-size:15px;font-weight:700;color:#fff}
.ts-m{font-family:var(--ff-m);font-size:11px;color:var(--mute);margin-top:3px;letter-spacing:.5px}
@media (max-width:820px){
  .ts-grid{grid-template-columns:1fr}
}
